export const INTERCONNECTED_WORLD_ACTIVITIES = [
// PHASE A — FONDASI (1-20)
{n:1,type:"mcq",micro:"Dunia yang terhubung",q:"'Dunia yang saling terhubung' berarti...",options:["apa yang terjadi & dibuat di satu tempat sering memengaruhi orang di tempat lain, kadang sangat jauh","hanya negara besar yang saling berhubungan","setiap negara hidup sepenuhnya sendiri tanpa hubungan apa pun"],answer:0,explain:"Barang, makanan, uang, orang, penyakit, cuaca, & gagasan bergerak melintasi batas negara. Kita hidup dalam satu jaringan besar.",hint:"Kejadian di satu tempat terasa di tempat lain."},
{n:2,type:"mcq",micro:"Dari mana barangnya",q:"Cara sederhana menyadari keterhubungan global saat memakai barang:",options:["tidak perlu memikirkannya","melihat label 'Buatan ...' atau memikirkan dari mana bahannya berasal","menganggap semua barang dibuat di kota kita"],answer:1,explain:"Baju, ponsel, cokelat, & alat tulis sering melewati beberapa negara sebelum sampai ke tangan kita.",hint:"Cek label & bahan asalnya."},
{n:3,type:"mcq",micro:"Perdagangan",q:"Negara berdagang (jual-beli antarnegara) terutama karena...",options:["semua negara memusuhi satu sama lain","perdagangan tidak ada gunanya","setiap negara punya sumber daya, iklim, & keahlian berbeda, sehingga saling melengkapi kebutuhan"],answer:2,explain:"Satu negara mungkin punya banyak minyak sawit tetapi butuh gandum; negara lain sebaliknya. Berdagang membuat keduanya terpenuhi.",hint:"Yang satu punya, yang lain butuh."},
{n:4,type:"tf",micro:"Makanan lintas negara",q:"Benar atau Salah: Sebagian makanan yang kita makan sehari-hari berasal dari tanaman atau bahan yang aslinya datang dari negara lain.",answer:true,explain:"Cokelat, kopi, gandum untuk roti & mi, serta banyak buah, bahan bakunya sering diimpor atau berasal dari tanaman yang dulu dibawa dari benua lain.",hint:"Cokelat & gandum, misalnya."},
{n:5,type:"mcq",micro:"Gagasan menyebar",q:"Selain barang, hal lain yang menyebar antarnegara:",options:["gagasan, musik, olahraga, ilmu pengetahuan, resep masakan, & cara menyelesaikan masalah","tidak ada yang menyebar selain uang","hanya barang yang bisa menyebar"],answer:0,explain:"Vaksin, rumus matematika, alfabet, sepak bola, & banyak lagu populer berpindah dari satu budaya ke budaya lain.",hint:"Bukan hanya benda fisik."},
{n:6,type:"mcq",micro:"Rantai pasok sederhana",q:"Sebuah cokelat batangan bisa melibatkan: petani kakao di satu negara, pabrik pengolah di negara lain, & toko di negaramu. Rangkaian ini disebut...",options:["daur ulang","rantai pasok (perjalanan sebuah produk dari bahan mentah hingga sampai ke pembeli)","kebetulan"],answer:1,explain:"Hampir setiap produk punya rantai pasok yang menghubungkan banyak orang di berbagai tempat.",hint:"Perjalanan produk dari kebun sampai ke tangan kita."},
{n:7,type:"tf",micro:"Peristiwa jauh, dampak dekat",q:"Benar atau Salah: Kekeringan atau bencana di negara yang jauh bisa memengaruhi harga makanan atau ketersediaan barang di negara kita.",answer:true,explain:"Bila panen gandum gagal di satu wilayah dunia, harga roti & mi di banyak negara lain bisa ikut naik karena pasokannya berkurang.",hint:"Pasokan berkurang di sana → harga naik di sini."},
{n:8,type:"mcq",micro:"Orang berpindah",q:"Orang berpindah antarnegara untuk berbagai alasan, seperti...",options:["tidak ada yang pernah pindah negara","hanya untuk berlibur","bekerja, belajar, berkumpul dengan keluarga, atau mencari keamanan dari bahaya"],answer:2,explain:"Perpindahan orang (migrasi) adalah bagian lama dari sejarah manusia & membawa pertukaran budaya serta keterampilan.",hint:"Kerja, sekolah, keluarga, keselamatan."},
{n:9,type:"mcq",micro:"Internet menghubungkan",q:"Internet membuat keterhubungan global...",options:["jauh lebih cepat: pesan, berita, uang, & ilmu bisa berpindah antarbenua dalam hitungan detik","hanya berlaku untuk permainan","melambat"],answer:0,explain:"Kamu bisa belajar dari guru di benua lain, atau melihat berita dari kota yang jauh secara langsung.",hint:"Hitungan detik antarbenua."},
{n:10,type:"tf",micro:"Saling bergantung",q:"Benar atau Salah: Negara-negara di dunia sepenuhnya mandiri & tidak ada yang bergantung pada negara lain untuk apa pun.",answer:false,explain:"Sebaliknya, hampir semua negara saling bergantung — untuk energi, pangan, teknologi, obat, atau pasar untuk menjual hasil produksinya.",hint:"Saling bergantung, bukan sepenuhnya mandiri."},
{n:11,type:"open",micro:"Keterhubungan di kamarmu",q:"Lihat sekeliling kamarmu atau tasmu. Sebutkan tiga benda & tebak dari mana bahan atau pembuatannya mungkin berasal (boleh negara atau daerah lain).",sample:"(1) Ponsel: komponennya mungkin dari beberapa negara di Asia Timur, logam langkanya bisa ditambang di Afrika. (2) Kaus katun: kapasnya mungkin ditanam di India atau Amerika, dijahit di pabrik di Asia Tenggara. (3) Cokelat di tas: kakaonya mungkin dari Afrika Barat atau Sulawesi, diolah di Eropa atau dalam negeri. Aku tidak yakin persis, tapi hampir tidak ada yang seluruhnya berasal dari kotaku sendiri.",explain:"Menyadari asal barang sehari-hari membuat keterhubungan global terasa nyata & dekat.",hint:"3 benda + tebakan asal bahan/pembuatannya."},
{n:12,type:"mcq",micro:"Manfaat keterhubungan",q:"Salah satu manfaat dunia yang terhubung:",options:["semua orang jadi persis sama","kita bisa mengakses obat, makanan, teknologi, & pengetahuan yang tidak dibuat di negara kita sendiri","tidak ada manfaatnya sama sekali"],answer:1,explain:"Keterhubungan memungkinkan berbagi vaksin, tanggap bencana bersama, & belajar dari penemuan negara lain.",hint:"Akses ke hal yang tak kita buat sendiri."},
{n:13,type:"mcq",micro:"Tantangan keterhubungan",q:"Salah satu tantangan dari dunia yang sangat terhubung:",options:["tidak ada tantangan apa pun","negara jadi terlalu mandiri","masalah seperti penyakit menular, krisis ekonomi, atau informasi salah juga bisa menyebar cepat lintas negara"],answer:2,explain:"Jaringan yang sama yang membawa manfaat juga bisa menyebarkan masalah dengan cepat, sehingga kerja sama antarnegara jadi penting.",hint:"Yang cepat menyebar bukan hanya hal baik."},
{n:14,type:"tf",micro:"Bahasa sebagai jembatan",q:"Benar atau Salah: Belajar bahasa lain tidak ada hubungannya dengan kemampuan seseorang terhubung dengan orang & gagasan dari penjuru dunia lain.",answer:false,explain:"Sebaliknya, bahasa membuka pintu ke budaya, buku, teman, & peluang belajar atau bekerja di tempat lain.",hint:"Bahasa membuka pintu."},
{n:15,type:"open",micro:"Kabar dari jauh",q:"Sebutkan satu hal yang kamu ketahui tentang negara atau budaya lain (makanan, olahraga, cerita, lagu, tokoh) & dari mana kamu mengetahuinya.",sample:"Aku tahu tentang bunga sakura & tradisi melihatnya bersama keluarga di Jepang. Aku tahu ini dari buku cerita, film animasi, & video di internet. Meski aku belum pernah ke sana, gagasan & gambarnya sampai kepadaku lewat berbagai media.",explain:"Kita sudah terhubung dengan dunia lewat hal-hal kecil yang kita nikmati & pelajari setiap hari.",hint:"1 hal dari budaya lain + sumbernya."},
{n:16,type:"mcq",micro:"Cuaca & iklim lintas batas",q:"Udara & lautan tidak berhenti di batas negara. Artinya...",options:["polusi udara atau sampah plastik di laut dari satu negara bisa terbawa & memengaruhi negara lain","setiap negara punya langit & laut sendiri yang terpisah","cuaca tidak pernah berpindah"],answer:0,explain:"Beberapa masalah lingkungan bersifat lintas batas, sehingga penyelesaiannya butuh kerja sama antarnegara.",hint:"Angin & arus laut tak kenal batas negara."},
{n:17,type:"order",micro:"Perjalanan sebuah kaus",q:"Urutkan perjalanan sederhana sebuah kaus katun sampai ke tokomu:",items:["Kapas ditanam & dipanen petani","Kapas dipintal jadi benang & ditenun jadi kain di pabrik","Kain dipotong & dijahit menjadi kaus","Kaus dikirim, sampai ke toko, & dibeli"],answer:[0,1,2,3],explain:"Dari kebun ke benang ke jahitan ke toko — sering melewati beberapa negara & ratusan pekerja.",hint:"Mulai dari kebun kapas."},
{n:18,type:"mcq",micro:"Ketergantungan yang sehat",q:"Saling bergantung antarnegara bisa menjadi hal yang baik bila...",options:["satu negara memaksakan kehendak pada yang lain","hubungannya adil & saling menguntungkan, & tiap negara tetap menjaga kebutuhan pentingnya sendiri","tidak ada aturan sama sekali"],answer:1,explain:"Keterhubungan paling sehat ketika berdasar pertukaran yang adil, bukan satu pihak yang selalu dirugikan.",hint:"Adil & saling menguntungkan."},
{n:19,type:"tf",micro:"Kita bagian dari dunia",q:"Benar atau Salah: Sebagai pelajar, hal-hal yang kita pelajari, konsumsi, & bagikan secara online tidak ada kaitannya sama sekali dengan dunia yang lebih luas.",answer:false,explain:"Sebaliknya, pilihan kita sehari-hari — barang yang kita beli, informasi yang kita sebar — adalah bagian kecil dari jaringan global yang besar.",hint:"Pilihan kecil kita pun bagian dari jaringan besar."},
{n:20,type:"mcq",micro:"Ringkasan Fondasi",q:"Inti memahami dunia yang saling terhubung:",options:["setiap negara terpisah sepenuhnya","hanya negara kaya yang terhubung","barang, orang, uang, gagasan, & masalah bergerak lintas negara, sehingga kita saling bergantung & keputusan di satu tempat bisa berdampak di tempat lain"],answer:2,explain:"Menyadari keterhubungan ini adalah langkah pertama menjadi warga dunia yang paham & bertanggung jawab.",hint:"Semua mengalir lintas batas; kita saling bergantung."},
// PHASE B — PEMAHAMAN (21-40)
{n:21,type:"classify",micro:"Melintasi batas atau tidak",q:"Kelompokkan hal-hal ini menurut apakah ia mudah melintasi batas negara:",items:["Berita & video di internet","Sebuah gunung","Penyakit menular","Sebuah danau kecil di desa"],groups:["Mudah melintasi batas negara","Tetap di satu tempat"],answer:{"Mudah melintasi batas negara":["Berita & video di internet","Penyakit menular"],"Tetap di satu tempat":["Sebuah gunung","Sebuah danau kecil di desa"]},explain:"Informasi & penyakit berpindah cepat lintas negara; bentang alam tertentu tetap di tempatnya (walau dampaknya bisa menyebar).",hint:"Mana yang bisa 'bepergian'?"},
{n:22,type:"mcq",micro:"Impor & ekspor",q:"'Mengimpor' berarti mendatangkan barang dari luar negeri; 'mengekspor' berarti...",options:["menjual & mengirim barang ke luar negeri","menghancurkan barang","menyimpan barang di gudang"],answer:0,explain:"Negara mengekspor yang bisa dihasilkannya banyak & mengimpor yang tidak bisa dihasilkannya cukup.",hint:"Ekspor = keluar, impor = masuk."},
{n:23,type:"mcq",micro:"Contoh saling bergantung",q:"Negara A pandai membuat mesin tetapi tidak punya banyak lahan pertanian; Negara B menghasilkan banyak beras tetapi belum punya pabrik mesin. Cara paling masuk akal:",options:["keduanya memaksakan diri membuat semuanya sendiri","A menjual mesin ke B, B menjual beras ke A — keduanya terpenuhi","A & B berhenti berhubungan"],answer:1,explain:"Ini contoh sederhana bagaimana perdagangan yang saling melengkapi menguntungkan kedua pihak.",hint:"Tukar kelebihan masing-masing."},
{n:24,type:"mcq",micro:"Berita global",q:"Saat gempa besar terjadi di satu negara, negara lain sering...",options:["menutup semua perbatasan","mengabaikannya sepenuhnya","mengirim bantuan, tim penyelamat, atau sumbangan — bentuk solidaritas antarbangsa"],answer:2,explain:"Tanggap bencana lintas negara menunjukkan sisi baik keterhubungan: manusia membantu manusia lain melewati batas.",hint:"Bantuan mengalir melintasi batas."},
{n:25,type:"tf",micro:"Harga & peristiwa dunia",q:"Benar atau Salah: Harga bahan bakar atau minyak goreng di suatu negara bisa dipengaruhi oleh peristiwa di belahan dunia lain, seperti konflik atau gagal panen.",answer:true,explain:"Karena banyak komoditas diperdagangkan secara global, gangguan pasokan di satu wilayah dapat menggerakkan harga di banyak negara.",hint:"Pasokan global → harga saling terkait."},
{n:26,type:"mcq",micro:"Budaya yang dipinjam",q:"Banyak hal yang kita anggap 'biasa' sebenarnya berasal dari budaya lain, contohnya...",options:["angka yang kita pakai, beberapa kata sehari-hari, jenis makanan, & olahraga tertentu","hanya nama-nama negara","tidak ada satu pun"],answer:0,explain:"Angka yang kita tulis, teh, kopi, badminton, & banyak kata serapan datang dari pertukaran budaya selama berabad-abad.",hint:"Angka, teh, olahraga tertentu."},
{n:27,type:"mcq",micro:"Rantai pasok terganggu",q:"Bila satu pabrik penting di luar negeri berhenti beroperasi karena bencana, akibat yang mungkin di negara lain:",options:["tidak ada akibat apa pun","barang tertentu (mis. suku cadang, obat, cip elektronik) jadi langka atau mahal untuk sementara","semua harga langsung turun"],answer:1,explain:"Ketika banyak negara bergantung pada satu titik pasokan, gangguan di titik itu terasa luas. Ini alasan sebagian negara berusaha punya beberapa sumber.",hint:"Satu titik putus, banyak yang terdampak."},
{n:28,type:"open",micro:"Manfaat & tantangan",q:"Tuliskan satu manfaat & satu tantangan dari kenyataan bahwa negaramu terhubung erat dengan dunia.",sample:"Manfaat: kami bisa mendapatkan obat, teknologi, & buku yang tidak diproduksi di dalam negeri, serta menjual hasil bumi ke pasar yang lebih besar. Tantangan: bila terjadi krisis ekonomi atau wabah di negara lain, dampaknya cepat terasa di sini juga, sehingga kami perlu siap & tidak bergantung sepenuhnya pada satu sumber.",explain:"Keterhubungan global punya dua sisi; warga yang paham menimbang keduanya.",hint:"1 manfaat + 1 tantangan."},
{n:29,type:"mcq",micro:"Kerja sama antarnegara",q:"Beberapa masalah (penyakit menular, pencemaran laut, penyelundupan) sulit diselesaikan satu negara sendirian karena...",options:["satu negara selalu bisa menyelesaikan segalanya","masalah itu tidak nyata","masalah itu melintasi batas negara, sehingga butuh aturan & tindakan bersama beberapa negara"],answer:2,explain:"Masalah lintas batas menuntut kerja sama: kesepakatan, berbagi informasi, & tindakan yang selaras.",hint:"Masalah lintas batas butuh solusi lintas batas."},
{n:30,type:"order",micro:"Bagaimana kabar menyebar global",q:"Urutkan bagaimana sebuah peristiwa lokal bisa jadi berita dunia:",items:["Peristiwa terjadi di sebuah kota","Warga & media setempat merekam & melaporkannya","Kantor berita & pengguna internet membagikannya lebih luas","Orang di negara lain membacanya & ikut menanggapi"],answer:[0,1,2,3],explain:"Dari kejadian lokal ke laporan ke penyebaran ke tanggapan global — sering dalam hitungan jam.",hint:"Mulai dari kejadian di satu kota."},
{n:31,type:"mcq",micro:"Ketergantungan berlebihan",q:"Mengapa sebuah negara sebaiknya tidak bergantung 100% pada satu negara lain untuk kebutuhan pokoknya (mis. pangan atau energi)?",options:["karena bila hubungan itu terganggu, negara tersebut bisa kesulitan; punya beberapa sumber lebih aman","karena negara lain selalu jahat","karena berdagang itu buruk"],answer:0,explain:"Keterhubungan yang sehat tetap menjaga ketahanan: cukup mandiri untuk kebutuhan penting, sambil tetap berdagang.",hint:"Jangan taruh semua telur di satu keranjang."},
{n:32,type:"tf",micro:"Pelajar & dunia",q:"Benar atau Salah: Keterhubungan global sepenuhnya urusan negara & perusahaan; seorang pelajar tidak punya peran apa pun di dalamnya.",answer:false,explain:"Sebaliknya, individu — termasuk pelajar — adalah simpul-simpul kecil di jaringan itu, lewat belajar bahasa, mengikuti berita global secara sehat, atau berteman dengan orang dari latar berbeda.",hint:"Pelajar pun bagian dari jaringan."},
{n:33,type:"mcq",micro:"Teknologi menyebar",q:"Ponsel pintar ditemukan & dikembangkan lewat kerja...",options:["satu orang saja di satu negara","banyak penemu, ilmuwan, & perusahaan dari berbagai negara selama puluhan tahun","tanpa siapa pun"],answer:1,explain:"Hampir semua teknologi besar adalah hasil gabungan gagasan dari banyak tempat & waktu.",hint:"Banyak tangan, banyak negara, banyak tahun."},
{n:34,type:"mcq",micro:"Uang lintas negara",q:"Ketika seseorang bekerja di luar negeri & mengirim uang ke keluarganya di kampung halaman, ini menunjukkan...",options:["pekerjaan di luar negeri tidak nyata","uang tidak bisa berpindah negara","aliran uang lintas negara yang membantu banyak keluarga & ekonomi daerah"],answer:2,explain:"Kiriman uang dari pekerja migran (remitansi) adalah salah satu bentuk keterhubungan ekonomi global yang paling langsung dirasakan keluarga.",hint:"Gaji di sana → keluarga di sini."},
{n:35,type:"mcq",micro:"Menghargai asal barang",q:"Menyadari bahwa banyak orang di berbagai negara terlibat membuat barang yang kita pakai sebaiknya membuat kita...",options:["lebih menghargai barang, tidak boros, & peduli apakah para pekerjanya diperlakukan adil","berhenti memakai barang apa pun","merasa barang itu tidak berharga"],answer:0,explain:"Di balik tiap produk ada rantai manusia. Kesadaran ini mendorong konsumsi yang lebih bertanggung jawab.",hint:"Ada banyak orang di balik satu barang."},
{n:36,type:"open",micro:"Bila keterhubungan terputus",q:"Bayangkan selama sebulan negaramu tidak bisa mengimpor atau mengekspor apa pun. Tuliskan dua hal yang mungkin jadi sulit & satu hal yang mungkin justru mendorong warga lebih mandiri.",sample:"Sulit: (1) beberapa obat & alat kesehatan yang bahannya diimpor bisa menipis; (2) harga barang elektronik & suku cadang naik karena stok terbatas. Yang mendorong kemandirian: warga & petani lokal mungkin terdorong menanam lebih banyak pangan sendiri & industri dalam negeri mencari cara membuat barang pengganti.",explain:"Membayangkan keterhubungan terputus membantu kita melihat betapa banyak yang kita terima darinya — & pentingnya keseimbangan dengan kemandirian.",hint:"2 kesulitan + 1 dorongan kemandirian."},
{n:37,type:"mcq",micro:"Informasi salah menyebar global",q:"Kabar bohong tentang suatu produk atau kelompok bisa menyebar ke banyak negara dalam sehari. Sikap warga dunia yang baik:",options:["ikut menyebarkan agar cepat viral","memeriksa kebenarannya ke sumber tepercaya sebelum membagikan, karena dampaknya bisa lintas negara","percaya semua yang datang dari luar negeri"],answer:1,explain:"Keterhubungan menuntut tanggung jawab: apa yang kita sebar bisa memengaruhi orang yang jauh & tak kita kenal.",hint:"Cek dulu; jangkauannya global."},
{n:38,type:"tf",micro:"Saling terhubung sejak dulu",q:"Benar atau Salah: Keterhubungan antarwilayah dunia adalah hal yang benar-benar baru & belum pernah ada sebelum internet.",answer:false,explain:"Sebaliknya, jalur perdagangan kuno seperti Jalur Sutra & pelayaran rempah sudah menghubungkan benua-benua ratusan hingga ribuan tahun lalu. Internet mempercepat, bukan memulai.",hint:"Jalur Sutra jauh sebelum internet."},
{n:39,type:"mcq",micro:"Keterhubungan & identitas",q:"Terhubung dengan dunia luas...",options:["membuat semua budaya hilang","memaksa kita meninggalkan budaya sendiri","bisa berjalan bersama tetap mencintai & menjaga budaya sendiri — kita bisa menghargai keduanya"],answer:2,explain:"Menjadi warga dunia tidak berarti kehilangan akar. Kita bisa bangga pada identitas lokal sambil terbuka pada dunia.",hint:"Akar sendiri + terbuka pada dunia."},
{n:40,type:"mcq",micro:"Ringkasan Pemahaman",q:"Dua sisi dari dunia yang terhubung yang perlu kita pegang bersama:",options:["manfaatnya (akses, kerja sama, pertukaran) & tantangannya (masalah menyebar cepat, ketergantungan), sehingga kita mengejar keterhubungan yang adil & tangguh","hanya sisi baiknya","hanya sisi buruknya"],answer:0,explain:"Warga dunia yang bijak menikmati manfaat keterhubungan sambil sadar & siap menghadapi risikonya.",hint:"Manfaat & tantangan, dipegang bersama."},
// PHASE C — PENERAPAN (41-60)
{n:41,type:"mcq",micro:"Terapan: melacak sarapan",q:"Saat sarapan roti dengan selai cokelat & teh, cara memikirkan keterhubungan global:",options:["semua bahan pasti dari kotaku","gandum roti bisa impor, kakao selai mungkin dari negara tropis lain, teh dari perkebunan yang bisa jadi jauh — satu piring melibatkan banyak tempat","makanan tidak berhubungan dengan dunia"],answer:1,explain:"Satu sarapan sederhana bisa menyatukan hasil kerja petani & pekerja dari beberapa benua.",hint:"Telusuri tiap bahan di piring."},
{n:42,type:"mcq",micro:"Terapan: proyek sekolah global",q:"Kelasmu ingin bertukar surat/video dengan sekolah di negara lain. Manfaat kegiatan ini:",options:["membuat kelas jadi sombong","tidak ada, buang waktu","belajar langsung tentang kehidupan sehari-hari, bahasa, & sudut pandang anak-anak di tempat lain, sekaligus melatih rasa hormat pada perbedaan"],answer:2,explain:"Pertukaran antarsekolah adalah cara nyata & aman merasakan keterhubungan global pada usia sekolah.",hint:"Belajar langsung dari sesama pelajar di tempat lain."},
{n:43,type:"mcq",micro:"Terapan: berita luar negeri",q:"Kamu membaca berita tentang kekeringan parah di negara pengekspor gandum. Pikiran warga dunia yang paham:",options:["'ini bisa memengaruhi harga roti & mi di sini; keluargaku mungkin perlu lebih hemat, & aku bisa memahami mengapa harga naik'","'berarti negara itu malas'","'itu bukan urusanku'"],answer:0,explain:"Menghubungkan peristiwa jauh dengan kehidupan sendiri adalah inti literasi global.",hint:"Hubungkan berita jauh dengan meja makanmu."},
{n:44,type:"open",micro:"Terapan: barang favorit",q:"Pilih satu barang yang kamu sukai (sepatu, gawai, permainan, makanan). Telusuri sebisamu: dari mana bahannya, di mana kira-kira dibuat, & berapa banyak jenis pekerjaan yang mungkin terlibat.",sample:"Barang: sepatu olahraga. Bahan: karet untuk sol (mungkin dari getah pohon karet di Asia Tenggara), kain & benang sintetis (dari pabrik kimia), lem, & tali. Dibuat: kemungkinan dijahit & dirakit di pabrik di Asia. Pekerjaan yang terlibat: petani karet, pekerja pabrik bahan, perancang sepatu, penjahit & perakit, pekerja gudang & pengiriman, sopir, & penjaga toko. Puluhan jenis pekerjaan di beberapa negara untuk satu pasang sepatu.",explain:"Menelusuri satu barang secara detail membuat rantai global yang biasanya tak terlihat menjadi nyata.",hint:"Bahan + tempat + jenis-jenis pekerjaan."},
{n:45,type:"mcq",micro:"Terapan: membantu lintas negara",q:"Setelah bencana besar di negara lain, cara pelajar ikut menunjukkan solidaritas global dengan aman:",options:["pergi sendiri ke lokasi bencana","ikut penggalangan bantuan resmi yang terpercaya di sekolah atau komunitas, & belajar tentang wilayah itu agar lebih peduli","mengkritik korban di media sosial"],answer:1,explain:"Solidaritas global bisa dimulai dari tindakan kecil yang terkoordinasi & dari usaha memahami.",hint:"Lewat jalur bantuan resmi + belajar tentang wilayahnya."},
{n:46,type:"order",micro:"Terapan: menelusuri kenaikan harga",q:"Harga cokelat di toko tiba-tiba naik. Urutkan cara menelusuri sebabnya secara global:",items:["Cari tahu dari mana sebagian besar kakao dunia berasal","Periksa apakah ada kabar cuaca buruk, hama, atau gangguan panen di wilayah itu","Periksa apakah biaya pengiriman atau nilai tukar mata uang juga berubah","Simpulkan: kenaikan harga lokal kemungkinan terkait peristiwa di rantai pasok global"],answer:[0,1,2,3],explain:"Harga lokal sering merupakan cermin dari kejadian di sepanjang rantai pasok internasional.",hint:"Mulai dari 'kakao dunia datang dari mana'."},
{n:47,type:"mcq",micro:"Terapan: konsumen yang sadar",q:"Mengetahui bahwa beberapa barang murah bisa dihasilkan dengan kondisi kerja yang buruk di negara lain, sikap konsumen yang bertanggung jawab:",options:["berhenti membeli apa pun selamanya","tidak peduli asalkan murah","bila memungkinkan, memilih produk yang lebih adil bagi pekerjanya, tidak boros, & mendukung upaya agar rantai pasok lebih manusiawi"],answer:2,explain:"Sebagai bagian dari rantai global, pilihan konsumen — walau kecil — ikut membentuk permintaan.",hint:"Pilih yang lebih adil bila bisa; hargai barang."},
{n:48,type:"tf",micro:"Terapan: belajar dari negara lain",q:"Benar atau Salah: Cara negara lain menyelesaikan masalah (transportasi, daur ulang, pendidikan) tidak mungkin berguna bagi kita & sebaiknya diabaikan.",answer:false,explain:"Sebaliknya, bertukar 'praktik baik' adalah salah satu manfaat besar keterhubungan — asalkan disesuaikan dengan keadaan setempat, bukan disalin mentah-mentah.",hint:"Ambil idenya, sesuaikan dengan keadaan kita."},
{n:49,type:"mcq",micro:"Terapan: teman daring lintas negara",q:"Kamu berteman daring dengan seseorang dari negara lain lewat komunitas hobi. Sikap aman & terbuka:",options:["nikmati bertukar cerita tentang budaya & hobi, tetap jaga data pribadi, & libatkan orang dewasa bila ada yang membuatmu tidak nyaman","menganggap semua orang asing berbahaya & menutup diri","langsung membagikan alamat rumah & data pribadi"],answer:0,explain:"Keterhubungan global membuka pertemanan lintas budaya; keamanan digital dasar tetap berlaku.",hint:"Terbuka pada budaya, hati-hati dengan data pribadi."},
{n:50,type:"mcq",micro:"Terapan: rantai pasok & sekolah",q:"Alat tulis, buku, & perangkat di sekolahmu sampai lewat rantai pasok. Cara menghargainya:",options:["merusaknya karena toh bisa beli lagi","merawat & memakai secukupnya, sadar bahwa banyak orang & sumber daya terlibat untuk menyediakannya","menimbunnya sebanyak mungkin"],answer:1,explain:"Menyadari rantai di balik barang mendorong kita merawat & tidak boros.",hint:"Rawat & pakai secukupnya."},
{n:51,type:"mcq",micro:"Terapan: peristiwa olahraga dunia",q:"Ajang olahraga internasional (mis. Olimpiade, Piala Dunia) menunjukkan keterhubungan global karena...",options:["tidak ada negara yang ikut","hanya soal menang-kalah","atlet dari hampir semua negara berkumpul, aturan bersama disepakati, & miliaran orang menonton peristiwa yang sama"],answer:2,explain:"Ajang seperti ini adalah contoh damai dari kerja sama global: aturan bersama, pertukaran budaya, & perhatian dunia pada satu peristiwa.",hint:"Aturan bersama + peserta sedunia + penonton sedunia."},
{n:52,type:"open",micro:"Terapan: ide dari luar untuk masalah lokal",q:"Pikirkan satu masalah kecil di sekolah atau lingkunganmu. Bayangkan kamu bisa belajar dari sekolah/kota lain di dunia. Ide apa yang mungkin berguna, & bagaimana kamu akan menyesuaikannya?",sample:"Masalah: banyak sampah plastik dari jajan di kantin. Ide dari tempat lain: beberapa sekolah menerapkan 'bawa wadah sendiri' dengan diskon kecil bagi yang membawa. Penyesuaian untuk sekolahku: mulai dari satu hari dalam seminggu, sediakan tempat cuci wadah sederhana, & kerja sama dengan penjual kantin agar tidak merepotkan mereka. Aku juga akan tanya apakah aturan itu adil bagi murid yang tidak punya wadah tambahan.",explain:"Literasi global yang praktis adalah kemampuan meminjam ide dari mana pun & menyesuaikannya dengan konteks sendiri.",hint:"Masalah + ide dari tempat lain + penyesuaian."},
{n:53,type:"mcq",micro:"Terapan: memahami barang impor mahal",q:"Sebuah buah impor harganya jauh lebih mahal daripada buah lokal sejenis. Penjelasan yang masuk akal:",options:["biaya pengiriman jarak jauh, pendinginan, pajak impor, & kelangkaan menambah harga; buah lokal lebih murah karena rantainya pendek","buah impor selalu lebih enak","penjualnya serakah, titik"],answer:0,explain:"Memahami komponen harga membantu kita jadi konsumen yang lebih cerdas & menghargai produk lokal.",hint:"Jarak & rantai panjang menambah biaya."},
{n:54,type:"tf",micro:"Terapan: bangga lokal & terbuka global",q:"Benar atau Salah: Membeli & mempromosikan produk lokal bisa berjalan bersamaan dengan tetap terbuka belajar & berdagang dengan dunia.",answer:true,explain:"Mendukung produsen lokal memperkuat ekonomi & ketahanan sendiri, sementara keterbukaan global memberi akses ke hal yang tak bisa kita hasilkan. Keduanya bisa seimbang.",hint:"Dukung lokal + tetap terbuka."},
{n:55,type:"mcq",micro:"Terapan: menghadapi stereotip",q:"Seorang teman berkata 'orang dari negara X pasti semuanya begini'. Tanggapan warga dunia yang baik:",options:["ikut menyetujui","ingatkan bahwa setiap negara berisi jutaan orang yang berbeda-beda, & anjuran untuk menilai orang satu per satu, bukan lewat cap kelompok","balas mencap negara lain"],answer:1,explain:"Keterhubungan global menuntut kita melawan generalisasi kasar tentang bangsa atau kelompok.",hint:"Jutaan orang berbeda, bukan satu cap."},
{n:56,type:"order",micro:"Terapan: proyek 'asal barang kelas'",q:"Urutkan langkah membuat proyek memetakan asal barang di kelas:",items:["Kumpulkan 10-15 barang milik kelas atau murid (dengan izin)","Catat label 'dibuat di ...' atau tebak asal bahan bila tak ada label","Tandai di peta dunia dari mana saja barang itu berasal","Diskusikan: apa yang mengejutkan, & apa artinya tentang keterhubungan kita"],answer:[0,1,2,3],explain:"Proyek sederhana ini mengubah konsep abstrak 'keterhubungan global' menjadi peta nyata yang bisa dilihat.",hint:"Kumpulkan barang dulu, diskusi terakhir."},
{n:57,type:"mcq",micro:"Terapan: kabar baik global",q:"Selain masalah, keterhubungan juga menyebarkan kabar & pencapaian baik, seperti...",options:["tidak ada kabar baik yang menyebar","hanya gosip","penemuan obat baru, keberhasilan melindungi satwa langka, atau cara bertani yang lebih hemat air"],answer:2,explain:"Memperhatikan kemajuan global, bukan hanya bencana, membuat kita lebih berimbang & termotivasi.",hint:"Penemuan & keberhasilan juga menyebar."},
{n:58,type:"mcq",micro:"Terapan: keputusan keluarga",q:"Keluargamu mempertimbangkan menanam sebagian sayur sendiri di pekarangan. Kaitannya dengan literasi global:",options:["ini contoh menyeimbangkan keterhubungan (membeli dari pasar/impor) dengan sedikit kemandirian pangan di tingkat rumah tangga","berarti menolak semua barang dari luar","tidak ada kaitan"],answer:0,explain:"Bahkan keputusan rumah tangga bisa dilihat sebagai bagian dari menyeimbangkan ketergantungan & ketahanan.",hint:"Sedikit mandiri, tetap terhubung."},
{n:59,type:"tf",micro:"Terapan: tanggung jawab bersama",q:"Benar atau Salah: Karena kita menikmati manfaat dari dunia yang terhubung, kita juga ikut memikul tanggung jawab untuk memperlakukan orang & lingkungan di sepanjang rantai global dengan adil.",answer:true,explain:"Menerima manfaat keterhubungan tanpa memikirkan dampaknya pada orang lain di rantai itu bukanlah sikap warga dunia yang bertanggung jawab.",hint:"Manfaat datang dengan tanggung jawab."},
{n:60,type:"mcq",micro:"Ringkasan Penerapan",q:"Menerapkan pemahaman tentang dunia yang terhubung berarti...",options:["menolak semua hal dari luar negeri","menelusuri asal barang, menghubungkan berita jauh dengan hidup sendiri, belajar dari tempat lain, & membuat pilihan konsumen yang lebih bertanggung jawab","menghafal nama semua negara"],answer:1,explain:"Literasi global yang hidup terlihat dari cara kita berbelanja, membaca berita, & memperlakukan orang lain di jaringan besar ini.",hint:"Telusuri, hubungkan, belajar, pilih dengan sadar."},
// PHASE D — PENALARAN (61-80)
{n:61,type:"mcq",micro:"Menimbang perdagangan bebas",q:"Membuka perdagangan luas dengan banyak negara punya sisi baik (barang lebih murah & beragam) & sisi yang perlu dijaga, yaitu...",options:["semua orang pasti dirugikan","tidak ada sisi yang perlu dijaga","sebagian produsen lokal bisa kalah bersaing & pekerjaan tertentu terdampak, sehingga perlu kebijakan yang melindungi & membantu mereka menyesuaikan diri"],answer:2,explain:"Kebijakan yang bijak menikmati manfaat perdagangan sambil membantu kelompok yang terdampak, bukan mengabaikan mereka.",hint:"Untung bagi konsumen, tantangan bagi sebagian produsen."},
{n:62,type:"mcq",micro:"Ketergantungan sebagai kekuatan atau kerentanan",q:"Ketergantungan antarnegara bisa menjadi...",options:["bisa keduanya: kekuatan (mendorong perdamaian & kerja sama karena saling butuh) sekaligus kerentanan (bila satu pihak memutus pasokan sebagai tekanan)","selalu kekuatan tanpa risiko","selalu kelemahan"],answer:0,explain:"Karena itu banyak negara mengejar 'ketergantungan yang seimbang': cukup terhubung untuk untung & damai, cukup beragam sumbernya untuk aman.",hint:"Bisa mengikat damai, bisa dipakai menekan."},
{n:63,type:"tf",micro:"Globalisasi & budaya lokal",q:"Benar atau Salah: Arus budaya global yang kuat bisa membuat sebagian tradisi atau bahasa lokal terancam bila tidak sengaja dijaga & diwariskan.",answer:true,explain:"Keterhubungan membawa manfaat sekaligus tekanan pada keragaman budaya. Menjaga bahasa & tradisi lokal adalah pilihan sadar yang penting.",hint:"Yang berharga perlu sengaja dijaga."},
{n:64,type:"mcq",micro:"Siapa yang diuntungkan",q:"Saat menilai sebuah kesepakatan dagang atau proyek internasional, pertanyaan penting:",options:["'Apakah terdengar modern?'","'Siapa yang diuntungkan, siapa yang menanggung biaya atau risikonya, & apakah pembagiannya adil?'","'Apakah negara besar yang mengusulkan?'"],answer:1,explain:"Keterhubungan yang adil dinilai dari pembagian manfaat & beban, bukan dari seberapa besar atau modern kedengarannya.",hint:"Untung bagi siapa, beban bagi siapa."},
{n:65,type:"mcq",micro:"Rantai pasok & etika",q:"Sebuah barang murah ternyata dibuat dengan merusak hutan & membayar pekerja sangat rendah. 'Harga murah' itu sebenarnya...",options:["tanda produk berkualitas","keuntungan bersih tanpa kekurangan","memindahkan sebagian biayanya ke lingkungan & pekerja yang tidak terlihat di label harga"],answer:2,explain:"Harga di label tidak selalu mencerminkan seluruh biaya nyata. 'Biaya tersembunyi' sering ditanggung orang & alam di tempat lain.",hint:"Biaya yang tak muncul di label tetap ditanggung seseorang."},
{n:66,type:"open",micro:"Menimbang dua sisi",q:"Sebuah pabrik asing dibuka di dekat kotamu, membawa banyak lapangan kerja tetapi juga menambah lalu lintas & risiko pencemaran. Tuliskan pertimbangan untuk kedua sisi & apa yang akan kamu tanyakan sebelum berpendapat.",sample:"Sisi positif: pekerjaan baru bagi warga, pemasukan pajak untuk fasilitas umum, keterampilan baru. Sisi yang perlu dijaga: kemacetan, kualitas udara & air, apakah warga lokal benar-benar dipekerjakan atau hanya jadi penonton. Yang akan kutanyakan: apa aturan lingkungan yang harus dipatuhi pabrik & siapa yang mengawasinya, berapa banyak pekerja lokal yang direkrut, & apakah ada rencana menangani lalu lintas. Baru setelah itu aku berpendapat.",explain:"Keputusan tentang proyek global-lokal menuntut menimbang manfaat ekonomi & biaya sosial-lingkungan, dengan pertanyaan yang jelas.",hint:"Manfaat + biaya + pertanyaan sebelum berpendapat."},
{n:67,type:"mcq",micro:"Kabar dari luar & bias",q:"Berita internasional yang sampai kepada kita sering...",options:["dipilih & dibingkai oleh media tertentu, sehingga sebaiknya kita membaca lebih dari satu sumber untuk gambaran yang lebih utuh","selalu bohong","sudah pasti lengkap & netral"],answer:0,explain:"Setiap sumber punya sudut pandang & keterbatasan. Membaca beberapa sumber membantu memahami peristiwa global dengan lebih adil.",hint:"Baca lebih dari satu sumber."},
{n:68,type:"mcq",micro:"Masalah global & tanggung jawab tak merata",q:"Untuk masalah global seperti pencemaran laut, adil bila...",options:["semua negara menanggung beban yang sama persis tanpa melihat kontribusinya","negara & pihak yang menyumbang lebih banyak pada masalah & lebih mampu, ikut menanggung tanggung jawab lebih besar, sambil semua tetap berperan","hanya negara kecil yang bertanggung jawab"],answer:1,explain:"Prinsip keadilan sering mempertimbangkan siapa yang paling berkontribusi pada masalah & siapa yang paling mampu membantu.",hint:"Tanggung jawab sepadan kontribusi & kemampuan."},
{n:69,type:"tf",micro:"Keterhubungan bukan berarti seragam",q:"Benar atau Salah: Dunia yang terhubung mau tidak mau memaksa semua orang menjadi sama & menghapus keberagaman budaya.",answer:false,explain:"Sebaliknya, tujuan yang sehat bukan keseragaman, melainkan pertukaran yang saling memperkaya sambil tiap budaya tetap punya ciri khasnya.",hint:"Terhubung ≠ seragam."},
{n:70,type:"order",micro:"Menilai klaim ekonomi global",q:"Kamu membaca 'menutup semua impor akan langsung membuat negara kita makmur'. Urutkan cara menilainya:",items:["Perjelas: barang apa saja yang diimpor & apakah ada gantinya di dalam negeri","Pikirkan akibat berantai: harga barang tertentu, pekerjaan yang bergantung pada bahan impor, kemungkinan negara lain membalas","Cari contoh nyata negara lain yang pernah mencoba kebijakan serupa & hasilnya","Simpulkan dengan hati-hati: kemungkinan lebih rumit daripada klaim satu kalimat itu"],answer:[0,1,2,3],explain:"Klaim ekonomi yang menjanjikan hasil besar & instan hampir selalu menyembunyikan akibat berantai yang perlu ditelusuri.",hint:"Perjelas dulu apa yang sebenarnya diimpor."},
{n:71,type:"mcq",micro:"Ketahanan vs efisiensi",q:"Mengandalkan satu pemasok termurah untuk barang penting itu efisien, tetapi rapuh. Pelajaran dari gangguan pasokan global:",options:["sebaiknya tidak berdagang sama sekali","harga termurah selalu pilihan terbaik","punya beberapa pemasok atau cadangan mungkin sedikit lebih mahal, tetapi membuat kita lebih tahan saat terjadi gangguan"],answer:2,explain:"Menyeimbangkan efisiensi (murah) & ketahanan (tahan guncangan) adalah pelajaran besar dari dunia yang saling bergantung.",hint:"Sedikit lebih mahal, jauh lebih tahan guncangan."},
{n:72,type:"tf",micro:"Aksi lokal, dampak global",q:"Benar atau Salah: Tindakan kecil satu orang tidak pernah bisa ikut membentuk dampak global, sekalipun banyak orang di banyak negara melakukan hal yang sama.",answer:false,explain:"Sebaliknya, dalam sistem yang terhubung, perubahan perilaku yang tersebar luas (mis. mengurangi sampah plastik) bisa menjumlah & menggeser permintaan serta norma secara global.",hint:"Banyak aksi kecil × banyak orang = dampak besar."},
{n:73,type:"mcq",micro:"Menghindari dua jebakan",q:"Dua sikap yang sama-sama kurang tepat terhadap keterhubungan global:",options:["menerima segalanya dari luar tanpa saringan, ATAU menolak segalanya dari luar tanpa berpikir","hanya membaca satu berita","hanya sikap pertama yang salah"],answer:0,explain:"Warga dunia yang bijak tidak silau pada segala yang asing, juga tidak menutup diri; ia memilih dengan pertimbangan.",hint:"Bukan menelan semua, bukan menolak semua."},
{n:74,type:"open",micro:"Keterhubungan & masa depanmu",q:"Bagaimana dunia yang saling terhubung mungkin memengaruhi pilihan belajar atau pekerjaan yang tersedia bagimu di masa depan? Tuliskan dua kemungkinan.",sample:"(1) Aku mungkin bisa belajar atau bekerja untuk lembaga di negara lain tanpa pindah, lewat kerja jarak jauh — jadi keterampilan bahasa & digital jadi penting. (2) Beberapa pekerjaan di kotaku bergantung pada permintaan dari luar negeri (mis. kerajinan, pariwisata, ekspor pertanian), jadi memahami pasar global bisa membantuku memilih bidang yang lebih tahan & berkembang.",explain:"Literasi global mencakup memahami bagaimana jaringan dunia membentuk peluang pribadi kita.",hint:"2 kemungkinan dampak pada belajar/pekerjaanmu."},
{n:75,type:"mcq",micro:"Data global & konteks",q:"Kamu melihat 'Negara X mengimpor 40% berasnya'. Untuk menilainya, kamu perlu tahu...",options:["warna bendera Negara X","apakah 40% itu naik atau turun dari tahun-tahun sebelumnya, dari berapa negara sumbernya, & apakah ada rencana meningkatkan produksi sendiri","siapa presiden Negara X"],answer:1,explain:"Satu angka tentang keterhubungan ekonomi butuh konteks (tren, keberagaman sumber, kebijakan) agar bermakna.",hint:"Satu angka butuh tren & konteks."},
{n:76,type:"tf",micro:"Kerja sama itu mungkin",q:"Benar atau Salah: Meski negara-negara sering bersaing, sejarah menunjukkan mereka juga mampu bekerja sama pada masalah besar, seperti memberantas penyakit tertentu atau menyepakati aturan penerbangan internasional.",answer:true,explain:"Contoh kerja sama global yang berhasil membuktikan bahwa mengatasi masalah bersama itu sulit tetapi mungkin.",hint:"Ada banyak contoh kerja sama yang berhasil."},
{n:77,type:"mcq",micro:"Menghubungkan skala",q:"Cara berpikir 'dari lokal ke global' yang sehat:",options:["hanya peduli pada lingkungan sendiri & menganggap dunia tidak relevan","hanya peduli pada dunia & mengabaikan lingkungan sendiri","mulai dari memahami & memperbaiki lingkungan terdekat, sambil menyadari kaitannya dengan pola yang lebih besar di dunia"],answer:2,explain:"Warga dunia yang berpijak kuat merawat yang dekat & memahami kaitannya dengan yang jauh — keduanya, bukan salah satu.",hint:"Rawat yang dekat, pahami kaitannya dengan yang jauh."},
{n:78,type:"mcq",micro:"Ketimpangan dalam jaringan global",q:"Dalam rantai global sebuah produk, sering kali...",options:["pihak di awal rantai (mis. petani bahan mentah) kadang mendapat bagian yang jauh lebih kecil daripada pihak di ujung — ini soal keadilan yang layak diperhatikan","petani selalu paling untung","semua pihak mendapat bagian keuntungan yang persis sama"],answer:0,explain:"Menyadari ketimpangan dalam rantai global adalah bagian dari literasi global yang matang & mendorong dukungan pada perdagangan yang lebih adil.",hint:"Bagian keuntungan sering tak merata di sepanjang rantai."},
{n:79,type:"tf",micro:"Warga dunia & warga negara",q:"Benar atau Salah: Seseorang tidak bisa menjadi warga negara yang baik & warga dunia yang peduli pada saat yang sama; harus memilih salah satu.",answer:false,explain:"Sebaliknya, keduanya saling melengkapi: mencintai & berkontribusi pada negeri sendiri sambil peduli pada kemanusiaan yang lebih luas.",hint:"Bukan memilih; keduanya sekaligus."},
{n:80,type:"mcq",micro:"Ringkasan Penalaran",q:"Sikap paling matang terhadap dunia yang saling terhubung:",options:["menerima atau menolak globalisasi secara mutlak","menimbang manfaat & biayanya, memperjuangkan keterhubungan yang adil & tangguh, menjaga budaya & ketahanan sendiri, sambil terbuka belajar & bekerja sama","menganggap semua negara lain sebagai ancaman"],answer:1,explain:"Literasi global yang dewasa bukan pro atau anti 'globalisasi', melainkan cerdas & adil dalam menyikapinya.",hint:"Timbang, perjuangkan yang adil & tangguh, tetap terbuka."},
// PHASE E — TANTANGAN (81-100)
{n:81,type:"mcq",micro:"Studi kasus: kelangkaan cip",q:"Suatu masa, banyak negara kesulitan membeli mobil & alat elektronik baru karena kekurangan cip komputer kecil yang sebagian besar dibuat di beberapa pabrik saja. Pelajaran utamanya:",options:["sebaiknya berhenti membuat elektronik","cip tidak penting","dunia terlalu bergantung pada sedikit titik produksi untuk barang penting; beberapa negara lalu berupaya membangun kapasitas sendiri & menganekaragamkan pasokan"],answer:2,explain:"Kasus ini menunjukkan bagaimana efisiensi ekstrem (produksi terpusat) menciptakan kerentanan global saat terjadi gangguan.",hint:"Terlalu terpusat = rapuh."},
{n:82,type:"open",micro:"Peta keterhubungan pribadi",q:"Buat 'peta keterhubungan' satu harimu: pilih 4 momen (bangun, sarapan, belajar, hiburan) & untuk tiap momen sebutkan satu cara kamu terhubung dengan dunia yang lebih luas.",sample:"Bangun: alarm dari ponsel yang komponennya dari beberapa negara. Sarapan: teh dari perkebunan yang mungkin jauh, roti dari gandum yang bisa jadi impor. Belajar: buku pelajaran memakai sistem angka yang berasal dari India & Arab, & aku menonton video penjelas dari kanal luar negeri. Hiburan: bermain gim daring dengan pemain dari beberapa negara & mendengarkan lagu berbahasa asing. Hampir setiap jamku menyentuh dunia yang lebih luas.",explain:"Memetakan keterhubungan pada hari sendiri membuat konsep besar ini menjadi konkret & personal.",hint:"4 momen + satu keterhubungan global tiap momen."},
{n:83,type:"mcq",micro:"Menimbang bantuan internasional",q:"Sebuah negara menerima bantuan pembangunan dari luar negeri. Bantuan itu paling bermanfaat bila...",options:["memperkuat kemampuan negara penerima untuk mandiri (pelatihan, infrastruktur, alih pengetahuan), bukan sekadar memberi lalu pergi","hanya menguntungkan negara pemberi","membuat negara penerima bergantung selamanya"],answer:0,explain:"Bantuan yang baik membangun kapasitas & kemandirian, sejalan dengan prinsip keterhubungan yang adil.",hint:"Membangun kemandirian, bukan ketergantungan."},
{n:84,type:"tf",micro:"Tanggung jawab konsumen global",q:"Benar atau Salah: Sebagai satu konsumen kecil, pilihan kita tidak pernah bisa memengaruhi praktik perusahaan besar di rantai global.",answer:false,explain:"Sebaliknya, ketika banyak konsumen menuntut produk yang lebih adil & ramah lingkungan, permintaan itu bisa menggeser kebijakan perusahaan seiring waktu.",hint:"Banyak suara kecil bisa menggeser permintaan."},
{n:85,type:"mcq",micro:"Studi kasus: penyakit menular",q:"Wabah penyakit menular di satu wilayah dengan cepat menjadi perhatian dunia karena...",options:["hanya media yang membesar-besarkan","perjalanan & perdagangan global bisa menyebarkannya lintas negara, sehingga deteksi dini & berbagi informasi antarnegara menjadi penting","penyakit tidak pernah menyebar"],answer:1,explain:"Kesehatan adalah contoh jelas mengapa keterhubungan menuntut kerja sama: sistem peringatan bersama, berbagi data, & dukungan untuk negara dengan sumber daya terbatas.",hint:"Yang menular ikut jalur perjalanan & dagang."},
{n:86,type:"order",micro:"Menelusuri dampak sebuah keputusan global",q:"Sebuah negara pengekspor besar melarang ekspor gandumnya untuk sementara. Urutkan penelusuran dampaknya:",items:["Pasokan gandum di pasar dunia berkurang","Harga gandum global naik","Negara pengimpor menghadapi harga roti & pakan ternak yang lebih tinggi","Sebagian keluarga menyesuaikan belanja; pemerintah mencari sumber lain atau bantuan"],answer:[0,1,2,3],explain:"Satu keputusan kebijakan di satu negara merambat lewat harga & pasokan hingga ke meja makan keluarga di negara lain.",hint:"Pasokan turun dulu, keluarga menyesuaikan terakhir."},
{n:87,type:"mcq",micro:"Keterhubungan digital & kedaulatan data",q:"Saat kita memakai aplikasi dari perusahaan asing, data kita bisa disimpan di server di negara lain. Ini memunculkan pertanyaan tentang...",options:["warna logo aplikasi","tidak ada yang perlu dipertanyakan","siapa yang bisa mengakses data itu, hukum negara mana yang berlaku, & bagaimana melindungi privasi warga — hal yang makin dipikirkan banyak negara"],answer:2,explain:"Keterhubungan digital membawa manfaat besar sekaligus pertanyaan baru tentang privasi, keamanan, & kedaulatan data.",hint:"Data lintas negara = pertanyaan hukum & privasi baru."},
{n:88,type:"open",micro:"Usulan keterhubungan yang lebih baik",q:"Tuliskan satu usulan sederhana (untuk sekolah, keluarga, atau dirimu) yang menikmati manfaat keterhubungan global sambil menjaga ketahanan atau keadilan. Jelaskan alasannya.",sample:"Usulan: di rumah, kami tetap membeli sebagian sembako dari petani & pasar lokal meski kadang sedikit lebih mahal, sambil tetap membeli barang yang memang harus impor. Alasan: mendukung petani lokal menjaga agar kalau terjadi gangguan pasokan global, sumber pangan terdekat tetap kuat; sementara keterbukaan tetap memberi kami akses ke obat & alat yang tak diproduksi di sini.",explain:"Ide baik tentang keterhubungan menyeimbangkan keterbukaan dengan ketahanan & keadilan, bukan memilih satu ekstrem.",hint:"Usulan + bagaimana ia seimbang."},
{n:89,type:"mcq",micro:"Membedakan fakta & opini global",q:"Pernyataan 'Impor tahun ini naik 12%' & 'Impor membuat negara kita lemah' — perbedaannya:",options:["yang pertama klaim data yang bisa dicek; yang kedua penilaian yang perlu argumen & bukti, & orang bisa berbeda pendapat","keduanya opini","keduanya fakta"],answer:0,explain:"Diskusi tentang keterhubungan global jadi lebih jernih bila kita memisahkan angka yang bisa diperiksa dari penilaian yang bisa diperdebatkan.",hint:"Angka bisa dicek; penilaian bisa diperdebatkan."},
{n:90,type:"tf",micro:"Belajar sepanjang hayat",q:"Benar atau Salah: Karena jaringan global terus berubah (teknologi, iklim, ekonomi, politik), memahaminya adalah proses belajar yang berkelanjutan, bukan sesuatu yang selesai sekali.",answer:true,explain:"Warga dunia yang baik terus memperbarui pemahamannya seiring perubahan dunia.",hint:"Dunia berubah; pemahaman perlu diperbarui."},
{n:91,type:"mcq",micro:"Empati lintas jarak",q:"Membaca tentang keluarga di negara lain yang terdampak banjir sebaiknya menumbuhkan...",options:["rasa lega karena bukan kita","empati & kesadaran bahwa mereka manusia dengan harapan & ketakutan seperti kita, yang mungkin butuh solidaritas","ketidakpedulian karena jauh"],answer:1,explain:"Literasi global tanpa empati menjadi sekadar data. Menyadari kemanusiaan bersama adalah inti menjadi warga dunia.",hint:"Mereka manusia seperti kita."},
{n:92,type:"mcq",micro:"Menyikapi produk lokal vs impor",q:"Cara paling seimbang menyikapi pilihan produk lokal & impor:",options:["selalu impor karena pasti lebih bagus","selalu tolak impor apa pun","utamakan lokal bila kualitas & harganya masuk akal untuk mendukung ekonomi & ketahanan sendiri, tetap terbuka pada impor untuk yang belum bisa dipenuhi lokal"],answer:2,explain:"Bukan aturan kaku, melainkan kebiasaan menimbang: dukung yang dekat, terima yang perlu.",hint:"Utamakan lokal yang wajar, terima impor yang perlu."},
{n:93,type:"open",micro:"Refleksi",q:"Setelah mempelajari topik ini, apa satu kebiasaan berpikir atau bertindak yang ingin kamu ubah atau mulai terkait posisimu sebagai bagian dari dunia yang terhubung?",sample:"Aku ingin mulai membaca setidaknya satu berita internasional seminggu dari sumber tepercaya & mencoba menghubungkannya dengan kehidupan di sekitarku — misalnya bagaimana harga atau ketersediaan barang di sini bisa terkait. Aku juga ingin lebih menghargai barang yang kupakai dengan menyadari banyaknya orang di berbagai tempat yang terlibat membuatnya.",explain:"Refleksi yang mengarah pada satu perubahan nyata membuat pembelajaran ini berdampak.",hint:"1 kebiasaan yang ingin diubah/dimulai + alasan."},
{n:94,type:"mcq",micro:"Keterhubungan & perdamaian",q:"Salah satu alasan negara yang berdagang & bekerja sama erat cenderung lebih jarang berperang satu sama lain:",options:["hubungan ekonomi & manusia yang erat membuat konflik jadi sangat merugikan kedua pihak, sehingga ada dorongan kuat menyelesaikan perselisihan lewat perundingan","perang itu menyenangkan","mereka tidak punya senjata"],answer:0,explain:"Saling ketergantungan bukan jaminan damai, tetapi sering menambah alasan & jalur untuk menghindari konflik.",hint:"Saling butuh menambah alasan berdamai."},
{n:95,type:"tf",micro:"Peran generasi muda",q:"Benar atau Salah: Generasi muda hari ini akan menghadapi tantangan global (iklim, teknologi, ekonomi) yang menuntut kerja sama lintas negara, sehingga belajar memahami dunia yang terhubung adalah bekal penting.",answer:true,explain:"Banyak masalah besar abad ini tidak bisa diselesaikan satu negara sendiri; memahami keterhubungan adalah keterampilan masa depan.",hint:"Tantangan besar butuh kerja sama lintas negara."},
{n:96,type:"mcq",micro:"Menolak dua kesalahan berpikir",q:"Dua kesalahan berpikir tentang dunia yang perlu dihindari:",options:["tidak ada kesalahan berpikir soal ini","'negara lain tidak ada urusannya dengan kita' & 'apa pun dari luar negeri pasti lebih baik'","hanya kesalahan pertama"],answer:1,explain:"Menutup diri sepenuhnya & mengagumi buta segala yang asing sama-sama menghalangi penilaian yang jernih.",hint:"Bukan menutup diri, bukan silau."},
{n:97,type:"mcq",micro:"Menghubungkan ke keterampilan lain",q:"Memahami dunia yang terhubung bekerja paling baik bila digabung dengan...",options:["tidak digabung dengan apa pun","menghafal peta saja","berpikir kritis (memeriksa klaim & sumber berita global), empati (menyadari kemanusiaan bersama), & kesadaran lingkungan (masalah lintas batas)"],answer:2,explain:"Literasi global adalah simpul yang menghubungkan berpikir kritis, kepedulian sosial, & kesadaran lingkungan.",hint:"Gabung dengan berpikir kritis, empati, & lingkungan."},
{n:98,type:"order",micro:"Dari sadar ke aksi",q:"Urutkan langkah mengubah kesadaran global menjadi tindakan bermakna:",items:["Pilih satu isu global yang benar-benar kamu pedulikan","Pelajari dari beberapa sumber tepercaya sampai kamu paham dasarnya","Cari tindakan lokal yang nyata & sesuai kemampuanmu (kebiasaan, proyek kecil, ikut kegiatan)","Jalankan, ajak orang lain, & tinjau dampaknya"],answer:[0,1,2,3],explain:"Pilih isu → pelajari → temukan aksi lokal → jalankan & ajak orang. 'Berpikir global, bertindak lokal.'",hint:"Pilih isu dulu, ajak orang lain terakhir."},
{n:99,type:"open",micro:"Definisi pribadi",q:"Dengan kata-katamu sendiri, tuliskan apa artinya bagimu menjadi 'bagian dari dunia yang saling terhubung' — dalam 2-3 kalimat.",sample:"Bagiku, itu berarti menyadari bahwa hidupku setiap hari ditopang oleh kerja orang-orang di banyak tempat yang tak kukenal, & bahwa pilihanku juga ikut menyentuh mereka. Aku ingin menikmati manfaat keterhubungan ini dengan rasa syukur & tanggung jawab: menghargai barang & orang di baliknya, memeriksa informasi sebelum menyebar, & peduli pada masalah bersama umat manusia sambil tetap berpijak & berkontribusi di lingkunganku sendiri.",explain:"Merumuskan makna pribadi membuat konsep ini menjadi bagian dari cara pandangmu, bukan sekadar materi.",hint:"2-3 kalimat, sungguh dengan katamu sendiri."},
{n:100,type:"mcq",micro:"Ringkasan Tantangan",q:"Inti memahami dunia yang saling terhubung:",options:["dunia adalah satu jaringan besar tempat barang, orang, uang, gagasan, & masalah mengalir lintas batas — sehingga kita perlu menimbang manfaat & tantangannya, mengejar keterhubungan yang adil & tangguh, & bertindak sebagai warga yang peduli baik pada lingkungan terdekat maupun pada kemanusiaan yang lebih luas","setiap negara sebaiknya menutup diri","keterhubungan hanya urusan pemerintah & perusahaan"],answer:0,explain:"Literasi tentang keterhubungan global adalah dasar untuk menjadi warga dunia yang paham, kritis, & bertanggung jawab.",hint:"Satu jaringan besar; timbang, perjuangkan yang adil, bertindak peduli."},
];
